  insert into public.map_quest_segments (quest_id, sort, name) values (74, 10, 'The feared Hugo') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 10, 'note', 'Bring a rope, a shovel, a machete, exani hur (or parcels), 8 skulls, the fruit (melon, banana, cherry, apple, grapes, coconut) and a white and a black knight. Talk to the four NPCs in this order.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Required Equipment: Rope, Shovel, Machete, Levitate spell or Parcels, 8 Skulls, Key 3620, Key 3899. Required items only for the first visitor of the tower that day: Melon, Banana, Cherry, Apple, Grapes, and Coconut; 1 White Knight Token and 1 Black Knight Token.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 20, 'talk', null, null, null, null, 'Oldrak', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Welcome <your name>! Rarely I can welcome visitors in these days."},{"say":"hugo","reply":"Ah, the bane of the Plains of Havoc, the hidden beast, the unbeatable foe. I live here for years and I am sure it''s only a myth."},{"say":"myth","reply":"There are many tales about the fearsome Hugo. It''s said it is an abomination, accidently created by Yenny the Gentle. It''s halve demon, halve something else and people say it''s still alive after dozens of years.","fx":["quest 211 becomes 1"],"cond":["quest 211 below 1"],"alts":[{"cond":["quest 211 above 0"],"reply":"There are many tales about the fearsome Hugo. It''s said it is an abomination, accidently created by Yenny the Gentle. It''s halve demon, halve something else and people say it''s still alive after dozens of years."}]}]'::jsonb, false, 'Find Oldrak (in Plains of Havoc temple) and talk with him. Say "hi", "hugo", "myth", "yenny the gentle".');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 30, 'talk', null, null, null, null, 'Zoltan', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Welcome <your name>, student of the arcane arts."},{"say":"yenny gentle","reply":"Ah, Yenny the Gentle was one of the founders of the druid order called Crunor''s Caress, that has been originated in her hometown Carlin."},{"say":"crunor caress","reply":"A quite undruidic order of druids they were, as far as we know. I have no more enlightening knowledge about them though.","fx":["quest 211 becomes 2"],"cond":["quest 211 is 1"],"alts":[{"cond":["quest 211 is 0"],"reply":"I am quite busy, ask another time!"}]}]'::jsonb, false, 'Go to Zoltan (in Noodles Academy of Modern Magic in Edron) and talk with him. Say "hi", "yenny the gentle", "crunor''s caress".');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 40, 'talk', null, null, null, null, 'Padreia', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Crunor''s blessings. I am glad to see you again, <your name>!","cond":["druids only"],"alts":[{"reply":"Welcome to our humble guild, wanderer. May I be of any assistance to you?"}]},{"say":"crunor caress","reply":"Don''t ask. They were only an unimportant footnote of history."},{"say":"footnote","reply":"They thought they have to bring Crunor to the people, if people did not find to Crunor of their own. To achieve that they founded the inn Crunor''s Cottage, south of Mt. Sternum.","fx":["quest 211 becomes 3"],"cond":["quest 211 is 2"],"alts":[{"cond":["quest 211 below 2"],"reply":"I have to attend other business, ask later please."}]}]'::jsonb, false, 'Go to Padreia (Druid Guild in Carlin) and talk to her. Say "hi", "crunor''s caress", "footnote".');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 50, 'talk', null, null, null, null, 'Lubo', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Welcome to my adventurer shop, <your name>! What do you need?"},{"say":"crunor cottage","reply":"Ah yes, I remember my grandfather talking about that name. This house used to be an inn a long time ago. My family bought it from some of these flower guys."},{"say":"flower guy","reply":"Oh, I mean druids of course. They sold the cottage to my family after some of them died in an accident or something like that."},{"say":"accident","reply":"As far as I can remember the story, a pet escaped its stable behind the inn. It got somehow involved with powerfull magic at a ritual and was transformed in some way."},{"say":"stable","reply":"My grandpa told me, in the old days there were some behind this cottage. Nothing big though, just small ones, for chicken or rabbits.","fx":["quest 211 becomes 4"],"cond":["quest 211 is 3"],"alts":[{"cond":["quest 211 below 3"],"reply":"Sorry speak louder I can''t hear you."}]}]'::jsonb, false, 'Go to Lubo (North of Thais, South of Mount Sternum) and talk to him. Say "hi", "crunor''s cottage", "flower guys", "accident", "stable". Now you know about the creation of the Demonbunny.');
  insert into public.map_quest_segments (quest_id, sort, name) values (74, 20, 'First visit to the Riddler') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 10, 'go', 'Dig here with your shovel and go down into the minotaur cave.', 32489, 31965, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Use your Shovel (or equivalent) to enter the cave, then travel as far north as possible and rope yourself up.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 20, 'go', 'Go as far north as you can, under the tower, and rope up here.', 32466, 31874, 8, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Travel as far north as possible and rope yourself up. You will emerge north of the Paradox Tower. There are only Minotaurs and Minotaur Archers in the cave.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 30, 'get', 'Take key 3899 from the dead tree. It''s trapped: you can lose up to 200 hp and poison fields may block the way out.', 32497, 31887, 7, null, null, '[[2970,1]]'::jsonb, null, '[]'::jsonb, false, 'Key 3899 is north of the Paradox Tower in a Dead Tree. The tree is booby trapped so you might lose up to 200 hp and Poison Fields may block your path to leave the tree.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 40, 'go', 'South of the Kazordoon entrance: exani hur up (or parcels) 4 times up the mountain, then use your rope twice.', 32571, 31976, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'To reach the Paradox Tower, go south of the entrance to Kazordoon and use the Levitate spell or parcels to climb up the "stairs" on the mountain.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 50, 'go', 'Put a skull on each of the 4 sacrificial stones and step on the switch in the middle: you''re teleported to the tower. (The strange carvings at the tower send you back here.)', 32566, 31957, 1, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'When you come across 4 Sacrificial Stones, place one skull on each stone and walk onto the Glowing Switch in the middle - you will be teleported to the tower. If you step on one of the four strange carvings, you will be teleported back away from the tower.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 60, 'go', 'You land south of the tower. Cut a path through the jungle grass with your machete to the switchplate and the door. Wait until the grass at the door grows back, then step on the plate and run to the stairs that appear inside the tower. Get your whole group inside first.', 32479, 31923, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Cut grass from point A to point D. Then cut to point B. After that, sit at point B and wait (~5 minutes) until the grass at the door starts growing back. Right when it does, step on point C and run to point D where stairs will have appeared.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 70, 'go', 'Set the 6 levers from left to right: right, right, left, left, right, left (the book reads backwards). Pull the lever: a ladder appears here.', 32476, 31904, 6, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'The next room will have a couple of bookshelves and a series of levers, which need to be in the following directions (from left to right): Right, Right, Left, Left, Right, Left. This is found out when reading the text in this book backwards.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 80, 'go', 'Pull the lever to make a ghoul appear. When it stands on the plate in the top left corner, the ladder appears: go up quickly.', 32478, 31904, 5, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'In the next room, flip the switch to make a Ghoul appear. If it stands on the right tile a ladder will appear until it walks away.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 90, 'key', null, 32479, 31903, 4, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'In this room you will need to use the Key 3899 that you got from the Dead Tree.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 100, 'go', 'Put the fruit on the tables from left to right: melon, banana, cherry, apple, grapes, coconut. Pull the lever: a ladder appears here.', 32476, 31904, 4, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Place the fruit on the tables in the following order (from left to right): melon, banana, cherry, apple, grapes, coconut. When the fruit is on the tables, flip the lever and a ladder will appear.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 110, 'go', 'Put the black and the white knight on the sides the two statues show and pull the lever: another ladder appears here.', 32479, 31904, 3, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'There will be two statues on the far wall. Examine them and place the black and white knight chess pieces on the correct sides and pull the lever. Another ladder will appear. Go up again.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 120, 'talk', 'Any colour works, but remember it. Answer "1 plus 1" with any number: it''s wrong, and you''re sent to Hellgate. Any other wrong answer and you have to start the test again.', null, null, null, 'Riddler', null, '[]'::jsonb, null, '[{"say":"hi","reply":"<your name>! HEHEHEHE! Another fool! Excellent!"},{"say":"test","reply":"Death awaits those who fail the test of the three seals! Do you really want me to test you?"},{"say":"yes","reply":"FOOL! Now you''re doomed! But well ... So be it! Let''s start out with the Seal of Knowledge and the first question: What name did the necromant king choose for himself?","fx":["quest 212 becomes 1"],"cond":["quest 212 is 0"],"alts":[{"cond":["quest 212 is 1"],"reply":"So you think you''re smart! But well ... So be it! Let''s start out with the Seal of Knowledge and the first question: What do I have in my pocket?"}]},{"say":"goshnar","reply":"HOHO! You have learned your lesson well. Question number two then: Who or what is the feared Hugo?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"demonbunny","reply":"HOHO! Right again. All right. The final question of the first seal: Who was the first warrior to follow the path of the Mooh''Tah?","cond":["quest 211 is 4"],"alts":[{"cond":["quest 211 not 4"],"reply":"Hmmm, so you think cheating will get you through that test? Then your final question of the first seal is: What is the meaning of life?"},{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"tha''kull","reply":"HOHO! Lucky you. You have passed the first seal! So ... would you like to continue with the Seal of the Mind?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"yes","reply":"As you wish, foolish one! Here is my first question: Its lighter then a feather but no living creature can hold it for ten minutes?","alts":[{"other":true,"reply":"HEHEHE! I knew you don''t have the stomach.","fx":["quest 212 becomes 0","ends the conversation"]}]},{"say":"breath","reply":"That was an easy one. Let''s try the second: If you name it, you break it.","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"silence","reply":"Hm. I bet you think you''re smart. All right. How about this: What does everybody want to become but nobody to be?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"old","reply":"ARGH! You did it again! Well all right. Do you wish to break the Seal of Madness?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"yes","reply":"GOOD! So I will get you at last. Answer this: What is your favourite colour?","alts":[{"other":true,"reply":"HEHEHE! I knew you don''t have the stomach.","fx":["quest 212 becomes 0","ends the conversation"]}]},{"say":"green","reply":"UHM UH OH ... How could you guess that? Are you mad??? All right. Question number two: What is the opposite?","fx":["quest 2 becomes 6"],"alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"none","reply":"NO! NO! NO! That can''t be true. You''re not only mad, you are a complete idiot! Ah well. Here is the last question: What is 1 plus 1?","alts":[{"other":true,"reply":"SORRY I AM NOT ALLOWD TO HELP HEHEHE!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]}]'::jsonb, false, 'There is a question that the Riddler will ask you: "What is your favorite color?". Any color will do the first time; however you have to answer with the same color the next time it is asked, and when you talk to A Prisoner. Because your last answer was wrong, you are sent to Hellgate.');
  insert into public.map_quest_segments (quest_id, sort, name) values (74, 30, 'The secret of mathemagics') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 10, 'go', 'The Riddler sends you to Hellgate. You meet skeletons, ghouls, rotworms, carrion worms and bonelords on the way out, maybe elder bonelords and demon skeletons.', 32725, 31589, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Because your last answer was wrong, you are sent to Hellgate. If you follow the maps you will only meet Skeletons, Ghouls, Rotworms, Carrion Worms and Bonelords, but be prepared to face Elder Bonelords, Demon Skeletons and possibly The Evil Eye.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 20, 'go', 'Walk out of Hellgate: down to the lowest floor, exani hur up twice, then up this ladder.', 32659, 31638, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'After following the path shown on 9th map, you have to levitate 2x then go up the ladder.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 30, 'go', 'Rope up through the wasp cave. If there''s no bridge upstairs, pull the switch in the room below first. Then walk to Ab''Dendriel and take the boat to Thais.', 32603, 31704, 8, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'There will be a room with a switch. The switch makes a bridge appear upstairs, pull it if after roping up there''s no bridge. Now you should be able to go out of the Wasp cave and walk to Ab''Dendriel. Take the boat from Ab''Dendriel to Thais.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 40, 'get', 'Mintwallin: take key 3620 from the drawers in the guards'' bedroom near the south gate.', 32411, 32155, 15, null, null, '[[2969,1]]'::jsonb, null, '[]'::jsonb, false, 'You may need to find Key 3620 to unlock a door, which is in the guards'' sleeping quarters near the south gates.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 50, 'key', null, 32393, 32136, 14, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'He is two levels up in the prison of Mintwallin. You may need to find Key 3620 to unlock a door.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 60, 'talk', 'Say the colour you told the Riddler (see your quest log). Remember the number he tells you.', null, null, null, 'A Prisoner', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Huh? What? I can see! Wow! A non-mino. Did they capture you as well?"},{"say":"math","reply":"My surreal numbers are based on astonishing facts. Are you interested in learning the secret of mathemagics?","cond":["quest 1 below 1"],"alts":[{"cond":["quest 1 above 0"],"reply":"You already know the secrets of mathemagics! Now go and use them to learn."}]},{"say":"yes","reply":"But first tell me your favourite colour please!"},{"say":"green","reply":"Very interesting. So are you ready to proceed in you lesson in mathemagics?","cond":["quest 2 is 6"],"alts":[{"other":true,"reply":"I think you are not in touch with yourself, come back if you have tuned in on your own feelings."}]},{"say":"yes","reply":"So know that everthing is based on the simple fact that 1 + 1 = 49!","fx":["quest 1 becomes 1"],"cond":["random answer 1 (the NPC picks one)"],"alts":[{"cond":["random answer 2 (the NPC picks one)"],"reply":"So know that everthing is based on the simple fact that 1 + 1 = 94!","fx":["quest 1 becomes 2"]},{"cond":["random answer 3 (the NPC picks one)"],"reply":"So know that everthing is based on the simple fact that 1 + 1 = 13!","fx":["quest 1 becomes 3"]},{"cond":["random answer 4 (the NPC picks one)"],"reply":"So know that everthing is based on the simple fact that 1 + 1 = 1!","fx":["quest 1 becomes 4"]}]}]'::jsonb, false, 'Talk with him and say "hi", "math", "yes", "<your color, see quest log>", "yes". A Prisoner will provide you with a number unique to you, which is ''the secret of mathemagics''. This is the number you have to tell Riddler.');
  insert into public.map_quest_segments (quest_id, sort, name) values (74, 40, 'Back to the Riddler') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 10, 'go', 'Up the mountain again: exani hur up (or parcels) 4 times, then use your rope twice.', 32571, 31976, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go back to the Paradox Tower and talk to Riddler again.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 20, 'go', 'Again a skull on each of the 4 stones, then the switch.', 32566, 31957, 1, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'You will need 4 skulls EVERY time you travel to the Paradox Tower.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 30, 'go', 'You land south of the tower. Cut the grass again and use the switchplate to make the stairs appear.', 32479, 31923, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'You will need to cut the grass and wait for it to grow back EVERY time you travel to the Paradox Tower.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 40, 'go', 'Up the ladder. The lever, fruit and knight puzzles stay solved until server save, unless someone switched the levers back.', 32476, 31904, 6, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'The fruits and chess pieces are only required to uncover the ladders to the floors above, and only need uncovering once per day unless someone else went there and switched back the levers or a floor reset has occurred.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 50, 'go', 'Wait for the ghoul again, then up the ladder quickly.', 32478, 31904, 5, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'You will need to wait for the Ghoul to step on the plate EVERY time you travel to the Paradox Tower.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 60, 'go', 'Up the ladder.', 32476, 31904, 4, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'When the fruit is on the tables, flip the lever and a ladder will appear. Go up the ladder.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 70, 'go', 'Up the ladder.', 32479, 31904, 3, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Another ladder will appear. Go up again.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 80, 'talk', 'The same answers. For "1 plus 1" say the prisoner''s number (see your quest log): you''re taken to the treasure room.', null, null, null, 'Riddler', null, '[]'::jsonb, null, '[{"say":"hi","reply":"<your name>! HEHEHEHE! Another fool! Excellent!"},{"say":"test","reply":"Death awaits those who fail the test of the three seals! Do you really want me to test you?"},{"say":"yes","reply":"FOOL! Now you''re doomed! But well ... So be it! Let''s start out with the Seal of Knowledge and the first question: What name did the necromant king choose for himself?","fx":["quest 212 becomes 1"],"cond":["quest 212 is 0"],"alts":[{"cond":["quest 212 is 1"],"reply":"So you think you''re smart! But well ... So be it! Let''s start out with the Seal of Knowledge and the first question: What do I have in my pocket?"}]},{"say":"goshnar","reply":"HOHO! You have learned your lesson well. Question number two then: Who or what is the feared Hugo?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"demonbunny","reply":"HOHO! Right again. All right. The final question of the first seal: Who was the first warrior to follow the path of the Mooh''Tah?","cond":["quest 211 is 4"],"alts":[{"cond":["quest 211 not 4"],"reply":"Hmmm, so you think cheating will get you through that test? Then your final question of the first seal is: What is the meaning of life?"},{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"tha''kull","reply":"HOHO! Lucky you. You have passed the first seal! So ... would you like to continue with the Seal of the Mind?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"yes","reply":"As you wish, foolish one! Here is my first question: Its lighter then a feather but no living creature can hold it for ten minutes?","alts":[{"other":true,"reply":"HEHEHE! I knew you don''t have the stomach.","fx":["quest 212 becomes 0","ends the conversation"]}]},{"say":"breath","reply":"That was an easy one. Let''s try the second: If you name it, you break it.","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"silence","reply":"Hm. I bet you think you''re smart. All right. How about this: What does everybody want to become but nobody to be?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"old","reply":"ARGH! You did it again! Well all right. Do you wish to break the Seal of Madness?","alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"yes","reply":"GOOD! So I will get you at last. Answer this: What is your favourite colour?","alts":[{"other":true,"reply":"HEHEHE! I knew you don''t have the stomach.","fx":["quest 212 becomes 0","ends the conversation"]}]},{"say":"green","reply":"UHM UH OH ... How could you guess that? Are you mad??? All right. Question number two: What is the opposite?","fx":["quest 2 becomes 6"],"alts":[{"other":true,"reply":"WRONG!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]},{"say":"none","reply":"NO! NO! NO! That can''t be true. You''re not only mad, you are a complete idiot! Ah well. Here is the last question: What is 1 plus 1?","alts":[{"other":true,"reply":"SORRY I AM NOT ALLOWD TO HELP HEHEHE!","fx":["ends the conversation","quest 212 becomes 0","teleports you to 32725, 31589, 12"]}]}]'::jsonb, false, 'Go back to the Paradox Tower and talk to Riddler again. He will ask you the same questions, and they have the same answers - just be sure to tell him the number that the prisoner gave you.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (74, seg, 90, 'note', 'Walk over exactly two switchplates to a chest: each plate destroys one of the four rewards. More plates, fewer rewards. The steps below are the pairs you can end up with.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'In the treasure room, there are four chests and two rows of Switchplates on the floor that you need to walk over to reach the chests. Each switch will DESTROY one of the rewards for you! If you step on more than two switchplates, you will lose more than two rewards!');
