-- =====================================================================================
-- Tibia Map - database step 17: AI drafts of quest guides from the TibiaWiki walkthroughs (slice 13j)
--
-- Run this once in Supabase (the house planner's project): SQL Editor -> New query -> paste everything -> Run.
-- Needs steps 3, 6, 7 and 9 and 16 (Key steps). Written by tools/drafts-to-sql.js from tools/data/quest-drafts. Every step is a draft
-- (not checked) with its wiki sentence as its source; what the checker couldn't tie to a real NPC, word, monster,
-- item or spot is a Note "Needs placing: ...". The quest's Reward steps from the old spots are moved into the draft.
-- Earlier drafts of these quests are replaced; a quest with anything made, changed or ticked in the app is skipped.
--
-- 32 steps for 1 quests (0 need placing):
--   The Paradox Tower Quest: 4 parts, 32 steps + 6 Reward steps
--       can't walk 32566,31957,1 -> 32479,31923,7 (You land south of the tower. Cut a path through the jungle grass with your machete to the switchplate and the door. Wait until the grass at the door grows back, then step on the plate and run to the stairs that appear inside the tower. Get your whole group inside first.): No route found: these two places are not connected.
--       can't walk 32479,31923,7 -> 32476,31904,6 (Set the 6 levers from left to right: right, right, left, left, right, left (the book reads backwards). Pull the lever: a ladder appears here.): The start is not near a tile you can walk on.
--       can't walk 32479,31902,2 -> 32725,31589,12 (The Riddler sends you to Hellgate. You meet skeletons, ghouls, rotworms, carrion worms and bonelords on the way out, maybe elder bonelords and demon skeletons.): No route found: these two places are not connected.
--       can't walk 32393,32136,14 -> 32393,32137,13 (Say the colour you told the Riddler (see your quest log). Remember the number he tells you.): No route found: these two places are not connected.
--       can't walk 32393,32137,13 -> 32571,31976,7 (Up the mountain again: exani hur up (or parcels) 4 times, then use your rope twice.): No route found: these two places are not connected.
--       can't walk 32566,31957,1 -> 32479,31923,7 (You land south of the tower. Cut the grass again and use the switchplate to make the stairs appear.): No route found: these two places are not connected.
--       can't walk 32479,31923,7 -> 32476,31904,6 (Up the ladder. The lever, fruit and knight puzzles stay solved until server save, unless someone switched the levers back.): The start is not near a tile you can walk on.
-- =====================================================================================

-- The Paradox Tower Quest
do $$
declare seg bigint; new_segs bigint[] := '{}'; sort_now integer;
begin
  if exists (select 1 from public.map_quest_steps where quest_id = 74 and not (id = any(array[16, 17, 18])) and (source is null or updated_by is not null or checked)) then return; end if;
  delete from public.map_quest_steps where quest_id = 74 and id = any(array[16, 17, 18]);
  delete from public.map_quest_steps where quest_id = 74 and source <> 'old quest spot';
  new_segs := new_segs || seg;
  new_segs := new_segs || seg;
  new_segs := new_segs || seg;
  new_segs := new_segs || seg;
  update public.map_quest_steps st set segment_id = seg, sort = 90 + r.n * 10 from (select id, row_number() over (order by sort, id) n from public.map_quest_steps where quest_id = 74 and source = 'old quest spot') r where st.id = r.id;
  select coalesce(max(sort), 90) into sort_now from public.map_quest_steps where segment_id = seg;
  delete from public.map_quest_segments s where s.quest_id = 74 and not (s.id = any(new_segs))
    and not exists (select 1 from public.map_quest_steps t where t.segment_id = s.id);
end $$;
